#!/usr/bin/env python3
import html,json,time
from pathlib import Path
CFG=Path('/etc/cloudif/production-targets.json');ROOT=Path('/var/lib/cloudif/production-window-guard');ACK=ROOT/'acknowledgements.jsonl';INC=ROOT/'incidents.jsonl';SLUG='atalhos-cloudif-iff1860746'
def read_json(p,default):
 try:return json.load(open(p))
 except Exception:return default
def data():
 cfg=read_json(CFG,{}).get(SLUG,{})
 latest=read_json(ROOT/'latest.json',{})
 alert=read_json(ROOT/'latest-alert.json',{})
 rows=[]
 try:
  for line in (ROOT/'alerts.jsonl').read_text().splitlines()[-50:]:
   try:rows.append(json.loads(line))
   except Exception:pass
 except Exception:pass
 acks=[]
 try:
  for line in ACK.read_text().splitlines()[-50:]:
   try:acks.append(json.loads(line))
   except Exception:pass
 except Exception:pass
 inc=[]
 try:
  for line in INC.read_text().splitlines()[-100:]:
   try:inc.append(json.loads(line))
   except Exception:pass
 except Exception:pass
 w=cfg.get('change_window') or {}
 return {'ok':True,'project_slug':SLUG,'target':{'mode':cfg.get('real_target_mode'),'url':cfg.get('real_target_url'),'sealed':cfg.get('real_target_mode')=='sealed','external_code':cfg.get('real_target_external_code'),'monitoring_enabled':cfg.get('monitoring_enabled')},'window':{'id':w.get('id'),'status':w.get('status'),'start_at':w.get('start_at'),'end_at':w.get('end_at'),'timezone':w.get('timezone'),'max_duration_seconds':w.get('max_duration_seconds'),'auto_reseal':w.get('auto_reseal'),'digest_sha256':w.get('digest_sha256'),'owner':w.get('owner') or cfg.get('change_owner'),'escalation':w.get('escalation') or cfg.get('change_escalation'),'open':cfg.get('change_window_open') is True},'guard':latest,'latest_alert':alert,'alerts':rows,'acknowledgements':acks,'incidents':inc,'controls':{'activation_allowed':cfg.get('activation_allowed') is True,'production_enabled':cfg.get('enabled') is True,'production_effects_enabled':cfg.get('production_effects_enabled') is True,'effect_tool_available':False,'restore_test_verified':cfg.get('restore_test_verified') is True,'canary_rollback_verified':cfg.get('real_canary_rollback_verified') is True,'snapshot_verified':cfg.get('snapshot_signature_verified') is True},'read_only':True,'secrets_exposed':False}
def esc(x):return html.escape(str(x if x not in (None,'') else '—'))
def badge(ok,yes='Ativo',no='Inativo'):return '<span class="ops-badge '+('ok' if ok else 'off')+'">'+(yes if ok else no)+'</span>'
def render(user=None,csrf_token=''):
 d=data();w=d['window'];c=d['controls'];a=d['latest_alert'];g=d['guard'];admin=bool((user or {}).get('admin'))
 ackids={str(x.get('alert_id')) for x in d.get('acknowledgements',[])}
 incident_latest={}
 for ev in d.get('incidents',[]):incident_latest[str(ev.get('alert_id'))]=ev
 alerts=''.join('<tr><td>'+esc(time.strftime('%d/%m/%Y %H:%M:%S',time.localtime(int(x.get('at') or 0))))+'</td><td>'+esc(x.get('severity'))+'</td><td>'+esc(x.get('kind'))+'</td><td>'+esc(x.get('owner'))+'</td><td>'+esc(x.get('escalation'))+'</td><td>'+((lambda aid,ev: ('<div class="incident-state"><b>'+esc((ev or {}).get('status') or ('acknowledged' if aid in ackids else 'pending'))+'</b>'+('<small>Responsável: '+esc((ev or {}).get('assignee'))+'</small>' if (ev or {}).get('assignee') else '')+'</div>'+('<div class="incident-actions"><form method="post" action="/cloudiff/portal/action/production-incident-assign"><input type="hidden" name="csrf_token" value="'+esc(csrf_token)+'"><input type="hidden" name="alert_id" value="'+esc(aid)+'"><input name="assignee" maxlength="100" placeholder="Responsável" required><input name="comment" maxlength="500" placeholder="Comentário" required><button class="btn">Atribuir</button></form><form method="post" action="/cloudiff/portal/action/production-incident-escalate"><input type="hidden" name="csrf_token" value="'+esc(csrf_token)+'"><input type="hidden" name="alert_id" value="'+esc(aid)+'"><input name="comment" maxlength="500" placeholder="Motivo" required><button class="btn">Escalar</button></form><form method="post" action="/cloudiff/portal/action/production-incident-mitigate"><input type="hidden" name="csrf_token" value="'+esc(csrf_token)+'"><input type="hidden" name="alert_id" value="'+esc(aid)+'"><input name="comment" maxlength="500" placeholder="Mitigação" required><button class="btn">Mitigar</button></form><form method="post" action="/cloudiff/portal/action/production-incident-close"><input type="hidden" name="csrf_token" value="'+esc(csrf_token)+'"><input type="hidden" name="alert_id" value="'+esc(aid)+'"><input name="comment" maxlength="500" placeholder="Causa raiz/encerramento" required><button class="btn red">Encerrar</button></form></div>' if admin and aid in ackids else ('<form method="post" action="/cloudiff/portal/action/production-alert-ack"><input type="hidden" name="csrf_token" value="'+esc(csrf_token)+'"><input type="hidden" name="alert_id" value="'+esc(aid)+'"><input name="comment" maxlength="300" placeholder="Comentário" required><button class="btn">Reconhecer</button></form>' if admin else ''))))(str(x.get('alert_id')),incident_latest.get(str(x.get('alert_id')))))+'</td></tr>' for x in reversed(d['alerts'][-12:])) or '<tr><td colspan="6">Nenhum alerta operacional registrado.</td></tr>'
 adminforms=('''<div class="card"><h2>Agendar janela futura</h2><form method="post" action="/cloudiff/portal/action/production-window-schedule" class="ops-form"><input type="hidden" name="csrf_token" value="'''+esc(csrf_token)+'''"><label>Início UTC<input type="datetime-local" name="start_at" required></label><label>Fim UTC<input type="datetime-local" name="end_at" required></label><label>Responsável<input name="owner" maxlength="100" value="cloudif-operations" required></label><label>Escalonamento<input name="escalation" maxlength="100" value="cloudif-security" required></label><button class="btn">Agendar sem abrir</button></form><form method="post" action="/cloudiff/portal/action/production-window-cancel"><input type="hidden" name="csrf_token" value="'''+esc(csrf_token)+'''"><button class="btn red">Cancelar agenda</button></form><p class="ops-note">Agendar não abre a janela e não habilita efeitos. A abertura real continua inexistente.</p></div>''' if admin else '')
 return f'''<section class="ops-shell"><div class="ops-hero"><div><span class="ops-eyebrow">Produção real</span><h1>Operação e segurança</h1><p>Visão somente leitura do alvo selado, janela de mudança, reseal automático e alertas.</p></div><div>{badge(d['target']['sealed'],'Alvo selado','Alvo não selado')}</div></div><div class="ops-grid"><article class="card"><h2>Alvo real</h2><p><b>Modo:</b> {esc(d['target']['mode'])}</p><p><b>URL:</b> <code>{esc(d['target']['url'])}</code></p><p><b>Resposta esperada:</b> HTTP {esc(d['target']['external_code'])}</p><p>{badge(d['target']['monitoring_enabled'],'Monitorado','Sem monitoramento')}</p></article><article class="card"><h2>Janela de mudança</h2><p><b>Status:</b> {esc(w['status'])}</p><p><b>Início:</b> {esc(w['start_at'])}</p><p><b>Fim:</b> {esc(w['end_at'])}</p><p><b>Timezone:</b> {esc(w['timezone'])}</p><p><b>Duração máxima:</b> {esc(w['max_duration_seconds'])} segundos</p><p>{badge(w['auto_reseal'],'Reseal automático','Reseal desativado')}</p><details><summary>Digest da janela</summary><code>{esc(w['digest_sha256'])}</code></details></article><article class="card"><h2>Responsabilidade</h2><p><b>Responsável:</b> {esc(w['owner'])}</p><p><b>Escalonamento:</b> {esc(w['escalation'])}</p><p><b>Último estado:</b> {esc(g.get('reason'))}</p><p><b>Severidade:</b> {esc(g.get('severity'))}</p><p><b>Último alerta:</b> {esc(a.get('kind'))}</p></article></div><div class="card"><h2>Gates da ativação</h2><div class="ops-gates"><div>{badge(c['snapshot_verified'],'Snapshot verificado','Snapshot pendente')}</div><div>{badge(c['restore_test_verified'],'Restore verificado','Restore pendente')}</div><div>{badge(c['canary_rollback_verified'],'Rollback canário verificado','Rollback pendente')}</div><div>{badge(w['open'],'Janela aberta','Janela fechada')}</div><div>{badge(c['activation_allowed'],'Ativação permitida','Ativação bloqueada')}</div><div>{badge(c['production_enabled'],'Produção ativa','Produção desativada')}</div><div>{badge(c['production_effects_enabled'],'Efeitos habilitados','Efeitos desabilitados')}</div><div>{badge(c['effect_tool_available'],'Ferramenta disponível','Ferramenta inexistente')}</div></div><p class="ops-note">Esta tela permite somente agendar/cancelar uma janela futura e reconhecer alertas. Ela não abre a janela, não habilita efeitos e não ativa produção.</p></div>{adminforms}<div class="card"><h2>Alertas operacionais</h2><div class="ops-table"><table><tr><th>Horário</th><th>Severidade</th><th>Evento</th><th>Responsável</th><th>Escalonamento</th><th>Reconhecimento</th></tr>{alerts}</table></div></div></section><style>.ops-shell{{display:grid;gap:18px}}.ops-hero{{display:flex;justify-content:space-between;align-items:center;padding:24px;border:1px solid var(--rule);border-radius:18px;background:var(--iff-wash)}}.ops-eyebrow{{font-size:.75rem;text-transform:uppercase;font-weight:900;color:var(--iff-dark)}}.ops-grid{{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}}.ops-badge{{display:inline-block;padding:7px 10px;border-radius:999px;font-weight:900;background:var(--rule-soft);color:var(--ink-2)}}.ops-badge.ok{{background:var(--iff-wash);color:var(--iff-dark)}}.ops-badge.off{{background:var(--halt-wash);color:var(--halt)}}.ops-gates{{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}}.ops-note{{margin-top:16px;padding:12px;border-left:4px solid var(--halt);background:var(--halt-wash);color:var(--ink)}}.ops-table{{overflow:auto}}.ops-table table{{width:100%;min-width:1100px}}.incident-state{{display:grid;gap:3px;margin-bottom:8px}}.incident-state small{{color:var(--ink-2)}}.incident-actions{{display:grid;gap:6px;min-width:320px}}.incident-actions form{{display:grid;grid-template-columns:1fr 1fr auto;gap:5px}}.ops-form{{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;align-items:end}}.ops-form label{{display:grid;gap:5px}}@media(max-width:900px){{.ops-form{{grid-template-columns:1fr 1fr}}.ops-grid{{grid-template-columns:1fr}}.ops-gates{{grid-template-columns:1fr 1fr}}.ops-hero{{align-items:flex-start;flex-direction:column;gap:12px}}}}@media(max-width:520px){{.ops-form{{grid-template-columns:1fr}}.ops-gates{{grid-template-columns:1fr}}}}</style>'''
